mapper.select:
SELECT s.ITEM_SHARE_ID, s.ITEM_ID, s.USERNAME, s.SHARE_TYPE, s.PERMISSION, s.ASSIGNED_BY, s.ASSIGNED_AT, s.CREATED_AT, s.CREATED_BY, i.CONTENT, ab.NAME AS ASSIGNED_BY_NAME FROM TB_ITEM_SHARE s INNER JOIN TB_ITEM i ON s.ITEM_ID = i.ITEM_ID LEFT JOIN TB_USER ab ON s.ASSIGNED_BY = ab.USERNAME WHERE s.USERNAME = #{username} AND i.STATUS NOT IN ('COMPLETED', 'DELETED')
AND s.SHARE_TYPE = #{shareType}
ORDER BY s.CREATED_AT DESC

mapper.update:
UPDATE TB_ITEM_SHARE
SET PERMISSION = #{permission},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

UPDATE TB_ITEM_SHARE
SET SHARE_TYPE = #{shareType},
    PERMISSION = #{permission},
    ASSIGNED_BY = #{assignedBy},
    ASSIGNED_AT = #{assignedAt},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

mapper.delete:
DELETE FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

mapper.select:
SELECT COUNT(*) > 0
FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

SELECT PERMISSION
FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}
